import type { NextConfig } from "next";

// Content-Security-Policy: moderate, integration-aware. Uses 'unsafe-inline'
// (no nonce infra yet) but still adds real protections — object-src none,
// base-uri/form-action self, frame-ancestors none, and script/frame allowlists
// for Stripe + analytics. connect-src is permissive to keep the console (wss)
// and API integrations working.
const csp = [
  "default-src 'self'",
  "base-uri 'self'",
  "object-src 'none'",
  "frame-ancestors 'none'",
  "form-action 'self'",
  "img-src 'self' data: blob: https:",
  "font-src 'self' data:",
  "style-src 'self' 'unsafe-inline'",
  "script-src 'self' 'unsafe-inline' 'unsafe-eval' https://plausible.io https://*.googletagmanager.com https://www.google-analytics.com https://js.stripe.com",
  "connect-src 'self' https: wss:",
  // blob: lets the webmail render an email body in a sandboxed blob:-URL iframe
  // (a `srcdoc` frame loads as about:srcdoc, which this frame-src refuses). The
  // frame stays fully sandboxed and inherits the rest of this CSP.
  "frame-src 'self' blob: https://js.stripe.com https://hooks.stripe.com",
  "worker-src 'self' blob:",
  "manifest-src 'self'",
  "upgrade-insecure-requests",
].join("; ");

const securityHeaders = [
  { key: "Content-Security-Policy", value: csp },
  { key: "X-Content-Type-Options", value: "nosniff" },
  // NOTE: X-Frame-Options is intentionally NOT set here — nginx already sends it,
  // and two conflicting values (DENY vs SAMEORIGIN) is undefined behaviour.
  // CSP `frame-ancestors 'none'` above is the authoritative, stricter control.
  { key: "Referrer-Policy", value: "strict-origin-when-cross-origin" },
  // microphone=(self): the Matrix build console offers voice-to-text (Web Speech
  // API), which the browser gates on the microphone permission policy. A bare
  // microphone=() disables the mic for the whole origin, so the mic button did
  // nothing at all. (self) grants it to our own pages only — third-party frames
  // still can't use it. camera/geolocation stay fully disabled (never used).
  { key: "Permissions-Policy", value: "camera=(), microphone=(self), geolocation=(), interest-cohort=()" },
  { key: "X-DNS-Prefetch-Control", value: "on" },
];

